UPDATE public.site_settings s SET value='{"eyebrow_tr":"KURUMSAL 3D ÜRETİM ÇÖZÜMLERİ","title_tr":"Tasarımınızdan\nüretiminizin\nbir parçasına.","lead_tr":"Ar-Ge, ürün geliştirme ve üretim ekipleri için 3D modelleme, fonksiyonel prototip ve küçük seri parça üretimi. Teknik ihtiyacınızı, uygulanabilir bir üretim planına dönüştürelim.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dyanimda' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"FİKİRDEN FİZİKSEL ÜRÜNE","title_tr":"Aklındaki fikir.\nElindeki gerçek.","lead_tr":"Bir eskiz, bir dosya ya da çözülmeyi bekleyen bir ihtiyaç. Fikrini birlikte geliştirelim, 3D üretimle hayata geçirelim.","cta_primary_tr":"Birlikte üretelim","cta_secondary_tr":"Neler mümkün?"}'::jsonb;
UPDATE public.site_settings s SET value='{"title_tr":"Bir parçadan fazlası.\nSürecinize uygun bir çözüm.","lead_tr":"Bir tasarımı doğrulamak, montajı kolaylaştırmak veya az adetli bir ihtiyacı karşılamak için. Üretim yöntemini kullanım koşulları, adet ve hedeflenen işlevle birlikte değerlendiriyoruz."}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dyanimda' AND s.key='autofocus_content' AND s.value='{"title_tr":"Üretmek istediğin şeyle başlayalım.","lead_tr":"İlk prototipten kişiye özel ürüne; kullanım amacını, malzemeyi ve üretim yöntemini projenle birlikte değerlendiriyoruz."}'::jsonb;
UPDATE public.site_settings s SET value='[{"id":"s1","title_tr":"Ürün geliştirme prototipleri","desc_tr":"Tasarım kararlarını fiziksel model üzerinden değerlendirmek için form, yerleşim ve montaj prototipleri.","link":"/teklif-al"},{"id":"s2","title_tr":"Montaj yardımcıları","desc_tr":"Tekrarlayan montaj ve konumlandırma adımları için projeye özel yardımcı parçalar.","link":"/teklif-al"},{"id":"s3","title_tr":"Özel muhafaza & aparatlar","desc_tr":"Elektronik cihazlar, test düzenekleri ve özel sistemler için geometriye uygun muhafazalar.","link":"/teklif-al"},{"id":"s4","title_tr":"Küçük seri üretim","desc_tr":"Kalıp yatırımından önce veya düşük adetli ihtiyaçlarda değerlendirilebilecek üretim alternatifleri.","link":"/teklif-al"}]'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dyanimda' AND s.key='services_cards' AND s.value='[{"id":"s1","title_tr":"Ürün prototipleri","desc_tr":"İlk prototipten kişiye özel ürüne; kullanım amacını, malzemeyi ve üretim yöntemini projenle birlikte değerlendiriyoruz.","link":"/teklif-al"},{"id":"s2","title_tr":"Kişiye özel tasarım","desc_tr":"İlk prototipten kişiye özel ürüne; kullanım amacını, malzemeyi ve üretim yöntemini projenle birlikte değerlendiriyoruz.","link":"/teklif-al"},{"id":"s3","title_tr":"Kurumsal hediyelik","desc_tr":"İlk prototipten kişiye özel ürüne; kullanım amacını, malzemeyi ve üretim yöntemini projenle birlikte değerlendiriyoruz.","link":"/teklif-al"},{"id":"s4","title_tr":"Küçük seri üretim","desc_tr":"İlk prototipten kişiye özel ürüne; kullanım amacını, malzemeyi ve üretim yöntemini projenle birlikte değerlendiriyoruz.","link":"/teklif-al"}]'::jsonb;
