UPDATE public.site_settings s SET value='{"eyebrow_tr":"ÜRETİM EKİPLERİ İÇİN EKLEMELİ İMALAT","title_tr":"Üretim hattınıza\nözel düşünülmüş\nparçalar.","lead_tr":"Fikstür, konumlandırma aparatı, test parçası ve cihaz muhafazası ihtiyaçlarınız için proje bazlı 3D üretim. Sahadaki gereksinimden numune değerlendirmesine kadar teknik bir süreç.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='3dsanayi' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"ÜRETİMİN İHTİYAÇ DUYDUĞU ÇÖZÜMLER","title_tr":"İyi fikirler,\nüretimde çalışır.","lead_tr":"Atölyedeki bir ihtiyacı işlevsel bir parçaya dönüştürelim. Prototip, montaj yardımcısı ve küçük seri üretim için birlikte çalışalım.","cta_primary_tr":"Birlikte üretelim","cta_secondary_tr":"Neler mümkün?"}'::jsonb;
