UPDATE public.site_settings s SET value='{"eyebrow_tr":"MİMARLIK & GAYRİMENKUL SUNUM ÇÖZÜMLERİ","title_tr":"Projenizin\nölçeği değişir.\nEtkisi büyür.","lead_tr":"Mimarlık ofisleri, gayrimenkul geliştiricileri ve proje ekipleri için ölçekli fiziksel modeller. Tasarım kararından yatırımcı sunumuna, detay seviyesi amaca göre belirlenir.","cta_primary_tr":"Teknik teklif alın","cta_secondary_tr":"Çözümleri inceleyin"}'::jsonb FROM public.tenants t WHERE s.tenant_id=t.id AND t.slug='maketyanimda' AND s.key='hero_content' AND s.value='{"eyebrow_tr":"TASARIMIN ÖLÇEĞİ DEĞİŞİR, ETKİSİ DEĞİL","title_tr":"Büyük fikirler.\nİnce detaylar.","lead_tr":"Çizimlerini dokunulabilir bir hikâyeye dönüştürelim. Mimari projeler, sunumlar ve sergileme için ölçekli maket çözümleri.","cta_primary_tr":"Birlikte üretelim","cta_secondary_tr":"Neler mümkün?"}'::jsonb;
